def gallery(prefix='',compact=False):
 pics=''.join(f'<figure><a class="gallery-link" href="{prefix}assets/{E(p["file"])}" data-caption="{E(p["caption"])}" aria-label="Ampliar foto: {E(p["caption"])}"><img src="{prefix}assets/{E(p["file"])}" alt="{E(p["alt"])}" width="600" height="650" loading="lazy" decoding="async"></a><figcaption>{E(p["caption"])}</figcaption></figure>' for p in GALLERY)
