 footer=f'''<footer class="footer"><div class="wrap"><p>© 2026 WEC Construcciones. Todos los derechos reservados.</p><p><a href="{prefix}informacion/">Información del servicio y privacidad</a></p></div></footer>'''

 floating=wa('',article['title'] if article else title,'floating','floating').replace(WA_ICON,f'<img src="{prefix}whatsapp.jpg" alt="WhatsApp para consultas" width="70" height="70">').replace('class="button floating wa-link"','aria-label="Consultar por WhatsApp" class="button floating wa-link"')
 analytics=f'''<script async src="https://www.googletagmanager.com/gtag/js?id={C['ga_id']}"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){{dataLayer.push(arguments)}}if(!['127.0.0.1','localhost'].includes(location.hostname)){{gtag('js',new Date());gtag('config','{C['ga_id']}');gtag('config','{C['ads_id']}');}}window.wecConversion='{C['ads_conversion']}';</script>'''
