 doc=f'''<!doctype html><html lang="es-AR"><head>{'<meta name="robots" content="noindex">' if path=='404/' else ''}<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(title)} | WEC Construcciones</title><meta name="description" content="{E(description)}"><link rel="canonical" href="{E(url)}"><meta name="theme-color" content="#FF6600"><meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:locale" content="es_AR"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(description)}"><meta property="og:url" content="{E(url)}"><meta property="og:image" content="{BASE}/assets/pozo-interior.webp"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="{prefix}assets/favicon.png"><link rel="stylesheet" href="{prefix}assets/site.css?v=2"><script type="application/ld+json">{schema_json}</script>{analytics}<script defer src="{prefix}assets/site.js?v=2"></script></head><body>{header}<main id="contenido">{body.replace('↗','').replace('↓','')}</main>{footer}{floating}<dialog class="lightbox" aria-label="Foto de trabajo realizado"><button class="lightbox-close" type="button" aria-label="Cerrar foto">Cerrar ×</button><figure><img alt=""><figcaption></figcaption></figure></dialog></body></html>'''
