allcards=''.join(f'<div class="filter-item" data-category="{E(a["category"])}" data-search="{E(a["title"]+" "+a["intro"])}">{cards([a],"../")}</div>' for a in ARTICLES)
body=f'<div class="wrap">{crumbs([("Guías útiles",None)],"../")}<section class="page-intro"><p class="eyebrow">50 guías · Problemas reales</p><h1>¿Qué necesitás<br>resolver?</h1><p>Precios, problemas de funcionamiento, obra nueva y biodigestores. Elegí tu tema y encontrá cómo iniciar una consulta.</p></section><section class="guide-library" aria-label="Biblioteca de guías"><div class="search-box"><label for="guide-search">Buscá una pregunta</label><input type="search" id="guide-search" placeholder="Probá con: se llena, precio, biodigestor…" autocomplete="off"><p class="search-hint">También podés buscar “pozo negro” o “poso ciego”.</p></div><div class="filters" role="group" aria-label="Filtrar por tema">{filters}</div><p class="result-count" aria-live="polite">50 guías para explorar</p><div class="guide-grid library-grid">{allcards}</div><p class="empty-results" hidden>No encontramos esa búsqueda. Probá con otra palabra o <a href="../#contacto">contanos tu caso</a>.</p></section>{contact()}</div>'
layout('guias/','Guías de pozos ciegos y biodigestores: 50 preguntas','Respuestas sobre pozos que se llenan, derrumbes, precios, obra nueva y biodigestores. Consultá tu caso por WhatsApp en CABA y GBA.',body,'CollectionPage')
# Artículos: intención única, tabla de contenido y enlaces relacionados.
for a in ARTICLES:
 related=[ARTICLES[i] for i in RELATIONS[ARTICLES.index(a)]]
 sections=''.join(f'<section id="parte-{i+1}"><h2>{E(h)}</h2><p>{E(p)}</p></section>' for i,(h,p) in enumerate(a['sections']))
 toc=''.join(f'<a href="#parte-{i+1}">{E(h)}</a>' for i,(h,p) in enumerate(a['sections']))
 q,answer=FAQ[a['slug']]
 sections+=f'<section class="article-question"><h2>{E(q)}</h2><p>{E(answer)}</p></section>'
 checks=''.join('<li>'+E(t)+'</li>' for t in a['check'])
 s=SERVICES[a['service']]
 extra=''
 if a['category']=='Biodigestores': extra='<p class="reference-note">Para un equipo concreto, consultá su documentación. Referencia: <a href="https://rotoplas.com.ar/rtp_resources/fichas-tecnicas/Manual-Biodigestor.pdf" target="_blank" rel="noopener noreferrer">manual de instalación y mantenimiento Rotoplas</a>. Las instrucciones pueden variar entre marcas y modelos.</p>'
 if a['slug'] in ['casa-sin-cloacas','llego-cloaca-que-hacer-pozo']:extra='<p class="reference-note">Para domicilios dentro del área de AySA: <a href="https://www.aysa.com.ar/portal/no-follow/tramites/Factibilidad_tecnica" target="_blank" rel="noopener noreferrer">consulta de factibilidad técnica</a>. Verificá el prestador correspondiente a tu propiedad.</p>'
 body=f'''<div class="wrap">{crumbs([('Guías útiles','../'),(a['category'],None)],'../../')}<header class="article-header"><p class="eyebrow">{E(a['category'])}</p><h1>{E(a['title'])}</h1><p class="article-lead">{E(a['intro'])}</p><div class="article-meta"><span>Por WEC Construcciones</span><span>14 de octubre de 2026</span><span>Guía para viviendas · CABA y GBA</span></div></header><div class="article-layout"><article class="article-body"><nav class="toc" aria-label="En esta guía"><span>EN ESTA GUÍA</span>{toc}</nav>{sections}<section class="article-checklist"><p class="eyebrow">Para avanzar con tu caso</p><h2>Qué información podés enviarnos</h2><ul>{checks}</ul><p>Con estos datos podemos orientar la consulta y definir qué relevamiento hace falta. El diagnóstico y el alcance de una obra dependen del lugar.</p>{wa('Consultar por mi caso',a['title'],placement='article-body')}</section>{extra}<p class="editorial-note">Esta guía explica criterios generales. La solución se define para la instalación y las condiciones de cada propiedad.</p></article><aside class="article-aside"><div class="aside-card"><p class="eyebrow">¿Te está pasando?</p><h2>Hablemos<br>de tu caso.</h2><p>Contanos tu localidad, qué cambió y qué necesitás resolver.</p>{wa('Escribinos',a['title'],placement='article-aside')}<span class="aside-area">CABA · Conurbano · Alrededores</span></div><a class="service-related" href="../../servicios/{a['service']}/"><span>Servicio relacionado</span><strong>{E(s['short'])}</strong>{ARROW}</a></aside></div>{gallery('../../',True)}<section class="section"><div class="section-head"><div><p class="eyebrow">Seguí explorando</p><h2>También puede servirte.</h2></div><a class="text-link" href="../">Todas las guías {ARROW}</a></div><div class="guide-grid">{cards(related,'../../')}</div></section>{contact(a['title'])}</div>'''
