raw=(ROOT/'404/index.html').read_text().replace('../',BASE+'/').replace('<head>','<head><meta name="robots" content="noindex">')
(ROOT/'404.html').write_text(raw)
# No indexar la ruta auxiliar de 404 ni el generador privado preexistente.
PAGES=[(p,t) for p,t in PAGES if p!='404/']
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{E(BASE+"/"+p)}</loc><lastmod>{C["publication_date"]}</lastmod></url>' for p,t in PAGES)+'</urlset>\n')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'/sitemap.xml\n')
(ROOT/'content/editorial-map.json').write_text(json.dumps([{'url':'guias/'+a['slug']+'/','intencion':a['title'],'grupo':a['category'],'servicio':a['service'],'relacionados':[ARTICLES[i]['slug'] for i in RELATIONS[ARTICLES.index(a)]]} for a in ARTICLES],ensure_ascii=False,indent=2)+'\n')
print(f'Generadas {len(PAGES)} páginas indexables y 50 artículos. Base: {BASE}')
